<script setup lang="ts">
import { motion } from "motion-v";
import { Swiper, SwiperSlide } from "swiper/vue";
import { Autoplay, Navigation } from "swiper/modules";
import type { Swiper as SwiperType } from "swiper";
import "swiper/css";

const props = defineProps(["gallery"]);

const modules = [Autoplay, Navigation];

// --- cursor arrow logic ---
const ARROW_SIZE = 80; // w-24/h-24 = 6rem = 96px

const sliderContainer = ref<HTMLElement | null>(null);
const swiperInstance = ref<SwiperType | null>(null);

const isHovering = ref(false);
const isLeftHalf = ref(true);
const cursorX = ref(0);
const cursorY = ref(0);

function onSwiperInit(swiper: SwiperType) {
  swiperInstance.value = swiper;
}

function onMouseMove(e: MouseEvent) {
  const el = sliderContainer.value;
  if (!el) return;
  const rect = el.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  cursorX.value = x - ARROW_SIZE / 2;
  cursorY.value = y - ARROW_SIZE / 2;
  isLeftHalf.value = x < rect.width / 2;
}

function onMouseEnter() {
  isHovering.value = true;
}

function onMouseLeave() {
  isHovering.value = false;
}

function onClick() {
  if (!swiperInstance.value) return;
  if (isLeftHalf.value) {
    swiperInstance.value.slidePrev();
  } else {
    swiperInstance.value.slideNext();
  }
}
</script>
