        @mousemove="onMouseMove"
        @mouseenter="onMouseEnter"
        @mouseleave="onMouseLeave"
        @click="onClick"
      >
        <Swiper
          :modules="modules"
          :navigation="{
            nextEl: '.gallery-next',
            prevEl: '.gallery-prev',
          }"
          :slides-per-view="1"
          :centered-slides="true"
          :space-between="0"
          :speed="500"
          :autoplay="true"
          class="h-full"
          :loop="true"
          @swiper="onSwiperInit"
        >
          <SwiperSlide
            class="w-full"
            v-for="(slide, index) in gallery"
            :key="index"
          >
            <div class="">
              <SanityImage
                v-if="slide.image"
                :image="slide.image"
                :alt="slide.title"
                :preserve-aspect-ratio="false"
                loading="lazy"
                sizes="(min-width: 1024px) 120vw, 100vw"
                class="aspect-[7/3] object-cover mb-auto"
              />
              <div
                class="absolute bottom-0 left-0 w-full bg-linear-to-b from-transparent to-[#0000007b] z-1"
              ></div>
            </div>
          </SwiperSlide>
        </Swiper>

